 const button=$('connect-top');if(button){button.disabled=(status.busy&&!status.background)||authRestoring||scopeHidden;button.classList.toggle('account-chip',display.connected);button.innerHTML=googleButtonContent({...display,busy:display.busy&&!status.background});button.setAttribute('aria-label',googleButtonLabel(display));}
