async function restoreAccountSession({quiet=false}={}){
 if(restorePromise)return restorePromise;
 if(cloudState.busy)return;
 restorePromise=(async()=>{
  const previous=workspaceStore.activeSub,observedEpoch=authEpoch,hadError=!!accountError;
  accountError='';
  if(!quiet){authRestoring=true;render();}
  try{
   const session=await cloud.restore();if(observedEpoch!==authEpoch){sessionNeedsCheck=true;return;}sessionCheckedAt=Date.now();sessionNeedsCheck=false;sessionResolved=true;
   cloudState=cloud.getStatus();
   if(scopeHidden||workspaceStore.activeSub!==(session.user?.sub||null))openWorkspaceFor(session.authenticated?session.user:null);
   authRestoring=false;
   if(session.authenticated&&workspaceStore.hasSavedWorkspace)render();
   if(session.authenticated){
    // The subject marker only notifies tabs. The server cookie verifies identity.
    try{const key='depositly.account.subject.v1';if(localStorage.getItem(key)!==session.user.sub){localStorage.setItem(key,session.user.sub);localStorage.setItem(AUTH_EVENT_KEY,JSON.stringify({type:'signed-in',nonce:crypto.randomUUID()}));}}catch{}
    await autoSync.sync();
   }else{try{localStorage.removeItem('depositly.account.subject.v1');}catch{}}
  }catch(error){
   if(observedEpoch===authEpoch)sessionNeedsCheck=false;
   cloudState=cloud.getStatus();
   if(!cloudState.connected&&workspaceStore.activeSub)openWorkspaceFor();
   if(scopeHidden)cloudState={...cloudState,connected:false,user:null};
   accountError=error.code==='AUTH_REQUIRED'?'Your Google access ended. Sign in again to open your account.':error.message;
  }finally{authRestoring=false;restorePromise=null;if(!quiet||previous!==workspaceStore.activeSub||accountError||scopeHidden||hadError)render();if(sessionNeedsCheck)setTimeout(()=>restoreAccountSession(),0);}
 })();
 return restorePromise;
}
