restoreAccountSession().then(()=>{const params=new URLSearchParams(location.search),error=params.get('auth_error');if(!error)return;params.delete('auth_error');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);const messages={ACCESS_DENIED:'Google sign-in was cancelled. You can try again whenever you’re ready.',AUTH_STATE_INVALID:'This sign-in attempt expired. Please start Google sign-in again.',OFFLINE_ACCESS_REQUIRED:'Google did not grant persistent access. Please sign in again and allow Depositly access to its app data.',AUTH_FAILED:'Google could not complete sign-in. Check the website’s Google callback and server settings.'};modal('Google account sign-in',`<p class="muted">${esc(messages[error]||'Sign-in could not be completed. Please try again.')}</p><div class="modal-footer"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="connect">Try Google again</button></div>`);});

document.addEventListener('keydown',event=>{const sidebar=$('sidebar');if(!sidebar?.classList.contains('open'))return;if(event.key==='Escape'){sidebar.classList.remove('open');document.querySelector('.menu-scrim').classList.remove('visible');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');document.querySelector('.mobile-menu').focus();}else if(event.key==='Tab'){const items=[...sidebar.querySelectorAll('button,a')];const index=items.indexOf(document.activeElement);if(event.shiftKey&&index<=0){event.preventDefault();items.at(-1).focus();}else if(!event.shiftKey&&(index===items.length-1||index<0)){event.preventDefault();items[0].focus();}}});

document.addEventListener('error',event=>{const target=event.target;if(target instanceof HTMLImageElement&&target.hasAttribute('data-account-photo'))target.closest('.account-avatar')?.classList.add('photo-failed');},true);
